def _cf_spec():
    _pkg = Path(__file__).parent if '__file__' in globals() else Path('../fastcflare')
    schema_dict = dict2obj((_pkg/'openapi.json').read_json())
    return SpecParser.from_openapi(schema_dict, cf_group_func)

